parameters.jsCode:
// Sélectionne le prochain mot-clé de la rotation pour ce compte, en tournant sur les runs successifs.
// Le compte de rotation est stocké côté Data Table (colonne rotation_index) pour persister entre les runs
// -- simplifié ici : on prend un index basé sur le timestamp du run pour répartir naturellement.
const account = $input.item.json;
const keywords = account.keywords_rotation || ["Business Developer", "Sales Manager", "Head of Sales"];
const idx = Math.floor(Date.now() / (1000 * 60 * 60 * 6)) % keywords.length;
return { json: { ...account, current_keyword: keywords[idx] } };

