parameters.jsCode:
// Branche 'true' (décideur business trouvé) : mappe le premier résultat people.
const item = $json.items[0];
return { json: { ...($('Décideur business trouvé ?').item.json), decision_maker_name: item.name, decision_maker_profile_url: item.profile_url || item.public_profile_url, decision_maker_role: item.headline || item.current_position, decision_maker_source: 'people' } };

// Branche 'false' (pas de décideur business trouvé) : fallback sur hiring_team de l'offre.
const source = $json;
const team = (source.hiring_team || [])[0];
if (!team) {
  return { json: { ...source, decision_maker_source: 'none', skip_message: true } };
}
return { json: { ...source, decision_maker_name: team.name, decision_maker_profile_url: team.profile_url, decision_maker_role: 'Recruteur / équipe RH (hiring_team)', decision_maker_source: 'hiring_team_fallback' } };

